import{_ as n}from"./chunks/Audio.COine8Wh.js";import{_ as t}from"./chunks/Tags.BJ536pW3.js";import{c as r,o as s,j as i,G as a,ae as o,a as l}from"./chunks/framework.Bw0Gm4PQ.js";const h=JSON.parse('{"title":"Consolidated Appropriations Act, 2026","description":"","frontmatter":{"legisId":"2026-02-03-consolidated-appropriations-act-2026","title":"Consolidated Appropriations Act, 2026","displayTitle":"Consolidated Appropriations Act, 2026","lawNumber":"119-75","billNumber":"H.R. 7148","sourceUrl":"https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ75.xml","publishDate":"2026-02-03T00:00:00-05:00","industries":["government-operations","defense","healthcare"],"agencies":["Department of Defense","Department of the Army","Department of the Navy","Department of the Air Force","United States Space Force","United States Africa Command","Office of Management and Budget","Intelligence Community","Department of Defense Office of Inspector General","Department of Labor","Occupational Safety and Health Administration","Mine Safety and Health Administration","Pension Benefit Guaranty Corporation","Department of Health and Human Services","Health Resources and Services Administration","Centers for Disease Control and Prevention","National Institutes of Health","Substance Abuse and Mental Health Services Administration","Centers for Medicare & Medicaid Services","Administration for Children and Families","Administration for Community Living","Food and Drug Administration","Department of Education","Social Security Administration","Corporation for National and Community Service","Department of Transportation","Federal Aviation Administration","Federal Highway Administration","Federal Motor Carrier Safety Administration","National Highway Traffic Safety Administration","Federal Railroad Administration","Federal Transit Administration","Maritime Administration","Pipeline and Hazardous Materials Safety Administration","Department of Transportation Office of Inspector General","Department of Housing and Urban Development","Department of Housing and Urban Development Office of Inspector General","United States Access Board","Federal Maritime Commission","Amtrak Office of Inspector General","National Transportation Safety Board","Surface Transportation Board","United States Interagency Council on Homelessness","Department of the Treasury","Internal Revenue Service","Financial Crimes Enforcement Network","Bureau of the Fiscal Service","Alcohol and Tobacco Tax and Trade Bureau","United States Mint","Executive Office of the President","Office of National Drug Control Policy","Supreme Court of the United States","United States Marshals Service","Commodity Futures Trading Commission","Federal Communications Commission","Federal Trade Commission","Securities and Exchange Commission","Consumer Product Safety Commission","Federal Election Commission","General Services Administration","National Archives and Records Administration","Small Business Administration","Department of State","United States Agency for International Development","United States Agency for Global Media","Peace Corps","Export-Import Bank of the United States","United States International Development Finance Corporation","Department of Homeland Security","United States Parole Commission","United States Sentencing Commission"],"head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Congress Bills\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Consolidated Appropriations Act, 2026\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills/2026-02-03-consolidated-appropriations-act-2026\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Consolidated Appropriations Act, 2026\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/congress-bills/2026-02-03-consolidated-appropriations-act-2026\\",\\"datePublished\\":\\"2026-02-03T00:00:00-05:00\\",\\"dateModified\\":1788887623000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/congress-bills/2026-02-03-consolidated-appropriations-act-2026\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"congress-bills/2026-02-03-consolidated-appropriations-act-2026.md","filePath":"congress-bills/2026-02-03-consolidated-appropriations-act-2026.md","lastUpdated":1788887623000}'),d={name:"congress-bills/2026-02-03-consolidated-appropriations-act-2026.md"},g=Object.assign(d,{setup(c){return(p,e)=>(s(),r("div",null,[e[0]||(e[0]=i("h1",{id:"consolidated-appropriations-act-2026",tabindex:"-1"},[l("Consolidated Appropriations Act, 2026 "),i("a",{class:"header-anchor",href:"#consolidated-appropriations-act-2026","aria-label":'Permalink to "Consolidated Appropriations Act, 2026"'},"​")],-1)),a(n),a(t,{list:"/congress-bills"}),e[1]||(e[1]=o('<p>Signed into law on Tuesday, February 3, 2026. Public Law 119-75, H.R. 7148.</p><p><strong>Headline:</strong> Congress funds major federal operations for 2026, extends temporary funding and renews key health, immigration, trade and insurance programs.</p><p><strong>Why it matters:</strong> The law finances defense, health, education, transportation, housing, diplomacy, courts, tax administration and other services while setting detailed spending restrictions. It also extends expiring programs and adds significant health care coverage, oversight and transparency rules.</p><p><strong>What the law does:</strong></p><ul><li>Funds military personnel, operations, weapons, research, health care, shipbuilding, intelligence activities and security assistance to partners.</li><li>Finances workforce programs, public health, biomedical research, Medicare, Medicaid, schools, student aid, Social Security and national service.</li><li>Supports highways, aviation, rail, transit, ports, pipeline safety, rental aid, public housing, homelessness services and affordable housing.</li><li>Funds tax administration, financial regulation, federal courts, small-business programs, federal buildings, election security and District of Columbia services.</li><li>Finances diplomacy, embassy security, global health, humanitarian relief, development and foreign security assistance while restricting aid to specified governments and entities.</li><li>Extends temporary federal funding through February 13, 2026, covers lapse-related personnel costs and approves qualifying essential obligations.</li><li>Extends flood insurance, cybersecurity, immigration, agriculture, trade-preference and criminal-justice authorities, including possible additional H-2B visas.</li><li>Extends Medicare and Medicaid programs, telehealth and community health funding while adding future coverage for qualifying multi-cancer tests and other treatments.</li><li>Requires stronger pharmacy benefit manager reporting and rebate pass-through rules and expands oversight of Medicare Advantage, pharmacies and drug programs.</li><li>Bars covered State Department and foreign-assistance payments to the United Nations Relief and Works Agency for the specified period.</li></ul><p><strong>Who it affects:</strong></p><ul><li>Service members, veterans, defense workers, federal employees and government contractors.</li><li>Patients, Medicare and Medicaid beneficiaries, health providers, pharmacies, employers and group health plans.</li><li>Students, schools, workers, job seekers, Social Security recipients and people with disabilities.</li><li>Renters, homeowners, public housing residents, travelers, transit riders and communities receiving infrastructure grants.</li><li>Taxpayers, small businesses, financial institutions, regulated companies, immigrants and temporary workers.</li><li>Foreign-aid recipients, diplomatic personnel, allied governments and international organizations.</li></ul><p><strong>Practical impact on a regular person:</strong></p><ul><li>Federal benefits and services receive 2026 funding, including health coverage, student aid, housing assistance, transportation and Social Security operations.</li><li>Travelers and communities may see continued infrastructure, airport, highway, rail, transit, port and safety investments.</li><li>Patients gain extended telehealth and community health support, while insured workers receive more visibility into prescription drug pricing and rebates.</li><li>Eligible students can receive Pell Grants of up to $6,335 for the 2026–2027 award year.</li></ul><p><strong>Context:</strong> The measure combines full-year appropriations for major departments with a short-term funding extension and multiple expiring-program renewals.</p><h2 id="breakdown" tabindex="-1">Breakdown <a class="header-anchor" href="#breakdown" aria-label="Permalink to &quot;Breakdown&quot;">​</a></h2><h3 id="division-a-department-of-defense-appropriations-act-2026-part-1-of-3" tabindex="-1">DIVISION A, DEPARTMENT OF DEFENSE APPROPRIATIONS ACT, 2026 (part 1 of 3) <a class="header-anchor" href="#division-a-department-of-defense-appropriations-act-2026-part-1-of-3" aria-label="Permalink to &quot;DIVISION A, DEPARTMENT OF DEFENSE APPROPRIATIONS ACT, 2026 (part 1 of 3)&quot;">​</a></h3><p>This part of the Department of Defense Appropriations Act, 2026 funds military personnel, operations, equipment purchases, research, health care, and other defense programs. It provides separate funding for the military services, reserve components, National Guard, defense-wide agencies, and selected intelligence-related accounts. It also sets conditions for counter-ISIS aid, environmental cleanup, shipbuilding, classified activities, and congressional reporting.</p><p><strong>Key takeaways:</strong></p><ul><li>The title funds pay, benefits, travel, training, and retirement costs for active-duty, reserve, and National Guard personnel.</li><li>It provides operating and maintenance funding for every military service, defense-wide agencies, reserve components, and the National Guard.</li><li>It funds major procurement programs, including aircraft, missiles, ammunition, combat vehicles, naval vessels, spacecraft, and other military equipment.</li><li>It supports defense research, development, testing, and evaluation across the Army, Navy, Air Force, Space Force, and defense-wide agencies.</li><li>It provides $342.5 million for vetted foreign forces and groups fighting ISIS, prohibits using that money for portable air-defense systems, and requires congressional notice and quarterly reports.</li><li>It funds military health care, environmental restoration, counter-drug activities, chemical weapons destruction, humanitarian aid, the Defense Department Inspector General, and specified intelligence-related accounts.</li></ul><h3 id="division-a-department-of-defense-appropriations-act-2026-part-2-of-3" tabindex="-1">DIVISION A, DEPARTMENT OF DEFENSE APPROPRIATIONS ACT, 2026 (part 2 of 3) <a class="header-anchor" href="#division-a-department-of-defense-appropriations-act-2026-part-2-of-3" aria-label="Permalink to &quot;DIVISION A, DEPARTMENT OF DEFENSE APPROPRIATIONS ACT, 2026 (part 2 of 3)&quot;">​</a></h3><p>This title sets government-wide rules for how the Department of Defense may spend, transfer, reprogram, and oversee its fiscal year 2026 funding. It imposes congressional notice and reporting requirements, domestic purchasing rules, contracting limits, and restrictions on changes to military forces, intelligence programs, and weapons activities. It also directs funding to specified defense, humanitarian, partner-assistance, shipbuilding, missile-defense, and military-family programs while canceling selected prior-year funds.</p><p><strong>Key takeaways:</strong></p><ul><li>The Defense Department generally must use funds within the current fiscal year, limit late-year spending, follow congressionally approved funding tables, and report or provide advance notice before many transfers, reprogrammings, special access programs, and major contracts.</li><li>The Secretary of Defense may transfer up to $6 billion for higher-priority unforeseen military needs, subject to Office of Management and Budget approval and congressional oversight, but may not restore items Congress denied.</li><li>The title favors domestic sourcing for items including anchor chain, steel plate, bearings, supercomputers, and United States flags, while allowing limited national-security or supply-based exceptions.</li><li>It provides targeted funding that includes $500 million for cooperative Israeli missile-defense programs, $50 million for vetted assistance to the Lebanese Armed Forces, $25 million for United States Africa Command cooperation, at least $79 million for the Civil Air Patrol, and grants totaling $49 million to the United Service Organizations and Red Cross.</li><li>It restricts certain force and weapons actions, including reductions in strategic delivery systems, retirement of C–40 aircraft, decommissioning more than one Littoral Combat Ship, nuclear-armed missile-defense interceptors, and reductions to specified reserve, weather-reconnaissance, and military-technician capabilities.</li><li>It cancels specified prior-year defense funds across shipbuilding, procurement, research, health, counterterrorism, and modernization accounts, while separately providing about $1.68 billion to cover prior-year Navy shipbuilding cost increases.</li></ul><h3 id="division-a-department-of-defense-appropriations-act-2026-part-3-of-3" tabindex="-1">DIVISION A, DEPARTMENT OF DEFENSE APPROPRIATIONS ACT, 2026 (part 3 of 3) <a class="header-anchor" href="#division-a-department-of-defense-appropriations-act-2026-part-3-of-3" aria-label="Permalink to &quot;DIVISION A, DEPARTMENT OF DEFENSE APPROPRIATIONS ACT, 2026 (part 3 of 3)&quot;">​</a></h3><p>This part of the 2026 defense funding law sets rules for intelligence transfers, Navy sealift, weapons programs, foreign security assistance, contracting, and congressional oversight. It directs funding to Taiwan, Jordan, the Baltic states, the defense industrial base, sexual-assault legal services, and other specified programs while reducing some operation, maintenance, and research accounts for expected savings or expired authority. It also restricts surveillance of Americans, certain foreign assistance, Guantanamo detainee transfers, prohibited contractors and research organizations, and changes to major aircraft, ship, missile-warning, and intelligence programs. The title requires public grant reporting and extensive notice and reporting to Congress on transfers, foreign contributions, unplanned military activities, overseas bases, and other spending.</p><p><strong>Key takeaways:</strong></p><ul><li>The intelligence community may transfer up to $1.5 billion for unforeseen, higher-priority intelligence needs with approval from the Office of Management and Budget, but not for items Congress denied.</li><li>The law funds Navy sealift and logistics activities, requires specified ship components to be made in the United States, and provides at least $80 million for a platform supply vessel pilot program.</li><li>The law provides major security assistance, including $1 billion for Taiwan, up to $500 million for Jordan, $200 million for Estonia, Latvia, and Lithuania, and nearly $1.5 billion for broader international security cooperation programs.</li><li>The law protects several major defense programs from cancellation or diversion of funds, including the Navy Next Generation Fighter, UH-60 Blackhawk, E-7 Wedgetail, and next-generation missile-warning satellite programs, while barring an alternative engine for the F-35.</li><li>The law prohibits defense funding for targeting Americans under specified surveillance authorities, assistance to the Azov Battalion or Taliban members, support for the Wuhan Institute of Virology, and most dealings with Rosoboronexport.</li><li>The law bars transferring covered Guantanamo detainees into the United States, limits transfers to foreign custody, prevents domestic facilities from being built or modified to house them, and prohibits closing or realigning the Guantanamo Bay naval station.</li></ul><h3 id="division-b-departments-of-labor-health-and-human-services-and-education-and-related-agencies-appropriations-act-2026-part-1-of-3" tabindex="-1">DIVISION B, DEPARTMENTS OF LABOR, HEALTH AND HUMAN SERVICES, AND EDUCATION, AND RELATED AGENCIES APPROPRIATIONS ACT, 2026 (part 1 of 3) <a class="header-anchor" href="#division-b-departments-of-labor-health-and-human-services-and-education-and-related-agencies-appropriations-act-2026-part-1-of-3" aria-label="Permalink to &quot;DIVISION B, DEPARTMENTS OF LABOR, HEALTH AND HUMAN SERVICES, AND EDUCATION, AND RELATED AGENCIES APPROPRIATIONS ACT, 2026 (part 1 of 3)&quot;">​</a></h3><p>This title funds the Department of Labor and its agencies for fiscal year 2026, including workforce training, apprenticeships, Job Corps, unemployment services, worker protections, labor statistics, veterans’ employment, and disability employment programs. It also funds benefits for injured workers, disabled coal miners, and workers affected by trade, while setting rules for how funds may be transferred, evaluated, and administered. The title includes temporary labor, overtime, workplace enforcement, Job Corps property, and department security provisions.</p><p><strong>Key takeaways:</strong></p><ul><li>The title provides nearly $4 billion for workforce training and employment services, including state grants for adults, youth, and dislocated workers and funding for registered apprenticeships, Native American programs, farmworkers, YouthBuild, people with criminal records, and community college training.</li><li>It provides about $1.76 billion for Job Corps, $395 million for community service employment for older Americans, and substantial funding for unemployment insurance administration, employment services, and workforce information systems.</li><li>It funds worker protection and labor oversight agencies, including workplace safety, mine safety, wage and hour enforcement, federal contractor compliance, employee benefits oversight, workers’ compensation, and the Pension Benefit Guaranty Corporation.</li><li>It supports veterans’ employment and transition services, including grants to states and programs for homeless veterans and veterans at risk of homelessness, and funds efforts to reduce employment barriers for people with disabilities.</li><li>The title limits certain OSHA enforcement against small farms and some low-injury-rate small employers, while preserving enforcement for complaints, serious hazards, major accidents, retaliation, and imminent dangers.</li><li>The title sets special rules for H-2B seafood workers and wages, creates a two-year overtime exemption for certain disaster claims adjusters, authorizes protective officers for senior Labor Department officials, and restricts closures of Job Corps centers.</li></ul><h3 id="division-b-departments-of-labor-health-and-human-services-and-education-and-related-agencies-appropriations-act-2026-part-2-of-3" tabindex="-1">DIVISION B, DEPARTMENTS OF LABOR, HEALTH AND HUMAN SERVICES, AND EDUCATION, AND RELATED AGENCIES APPROPRIATIONS ACT, 2026 (part 2 of 3) <a class="header-anchor" href="#division-b-departments-of-labor-health-and-human-services-and-education-and-related-agencies-appropriations-act-2026-part-2-of-3" aria-label="Permalink to &quot;DIVISION B, DEPARTMENTS OF LABOR, HEALTH AND HUMAN SERVICES, AND EDUCATION, AND RELATED AGENCIES APPROPRIATIONS ACT, 2026 (part 2 of 3)&quot;">​</a></h3><p>This title funds the Department of Health and Human Services for fiscal year 2026, including public health, biomedical research, Medicare and Medicaid administration, mental health and substance use services, child and family programs, aging and disability services, and emergency preparedness. It sets spending amounts and program conditions, permits limited transfers, requires reporting and oversight, and establishes rules for family planning, NIH grants, health care fraud prevention, and the care of unaccompanied children. It also cancels $1.826 billion in unused balances from the HHS Nonrecurring Expenses Fund.</p><p><strong>Key takeaways:</strong></p><ul><li>The title provides major funding for HRSA, CDC, NIH, SAMHSA, CMS, the Administration for Children and Families, the Administration for Community Living, and federal health emergency preparedness.</li><li>It funds Medicaid grants, Medicare trust funds and administration, community health and workforce programs, biomedical research, mental health and substance use treatment, Head Start, child care, home energy assistance, foster care, and refugee services.</li><li>It directs targeted funding to programs including the National Health Service Corps, rural hospitals, the Ryan White HIV/AIDS Program, universal flu vaccine research, maternal health research, Certified Community Behavioral Health Clinics, and opioid response grants.</li><li>Family planning funds may not be used for abortions, pregnancy counseling must be nondirective, and funded providers must encourage family involvement and comply with state reporting laws concerning abuse and sexual offenses.</li><li>The title requires safeguards, monitoring, congressional access, and public reporting for facilities housing unaccompanied children, while allowing temporary use of unlicensed facilities during an influx or emergency under specified conditions.</li><li>It imposes financial and oversight controls, including limits on fund transfers and certain salaries, reporting on Affordable Care Act staffing and exchange spending, NIH misconduct-investigation requirements, and dedicated funding to combat fraud, waste, and abuse in Medicare, Medicaid, and CHIP.</li></ul><h3 id="division-b-departments-of-labor-health-and-human-services-and-education-and-related-agencies-appropriations-act-2026-part-3-of-3" tabindex="-1">DIVISION B, DEPARTMENTS OF LABOR, HEALTH AND HUMAN SERVICES, AND EDUCATION, AND RELATED AGENCIES APPROPRIATIONS ACT, 2026 (part 3 of 3) <a class="header-anchor" href="#division-b-departments-of-labor-health-and-human-services-and-education-and-related-agencies-appropriations-act-2026-part-3-of-3" aria-label="Permalink to &quot;DIVISION B, DEPARTMENTS OF LABOR, HEALTH AND HUMAN SERVICES, AND EDUCATION, AND RELATED AGENCIES APPROPRIATIONS ACT, 2026 (part 3 of 3)&quot;">​</a></h3><p>This part of the 2026 appropriations law funds the Department of Education, national service programs, Social Security operations, labor-related boards, disability institutions, museums and libraries, and other related agencies. It supports aid for disadvantaged students, special education, student financial aid, higher education, career and adult education, education research, AmeriCorps, Supplemental Security Income, and agency oversight. It also sets spending controls, reporting duties, program conditions, and government-wide restrictions for the funded agencies while canceling or withholding specified unused funds.</p><p><strong>Key takeaways:</strong></p><ul><li>The law provides major funding for disadvantaged schools, school improvement, English learners, special education, career and adult education, higher education, and education research.</li><li>It provides $24.6 billion for federal student aid, sets the maximum Pell Grant at $6,335 for the 2026–2027 award year, and requires stronger accountability and transparency in federal student loan servicing.</li><li>It funds disability-related education and employment services, including vocational rehabilitation, the American Printing House for the Blind, the National Technical Institute for the Deaf, and Gallaudet University.</li><li>It funds AmeriCorps and other national service activities, including $180 million for the National Service Trust, and allows prorated education awards in certain cases when service ends early for reasons outside a participant’s control.</li><li>It funds Supplemental Security Income benefits and Social Security administration, including disability reviews, eligibility checks, fraud investigations, information technology, and inspector general oversight.</li><li>The law restricts the use of funds for abortion except in specified circumstances, embryo-damaging research, lobbying, certain drug-legalization advocacy, pornography access on government-funded networks, and sterile needles or syringes for illegal drug injection, and it rescinds or withholds billions of dollars in previously provided funds.</li></ul><h3 id="division-d-transportation-housing-and-urban-development-and-related-agencies-appropriations-act-2026-part-1-of-4" tabindex="-1">DIVISION D, TRANSPORTATION, HOUSING AND URBAN DEVELOPMENT, AND RELATED AGENCIES APPROPRIATIONS ACT, 2026 (part 1 of 4) <a class="header-anchor" href="#division-d-transportation-housing-and-urban-development-and-related-agencies-appropriations-act-2026-part-1-of-4" aria-label="Permalink to &quot;DIVISION D, TRANSPORTATION, HOUSING AND URBAN DEVELOPMENT, AND RELATED AGENCIES APPROPRIATIONS ACT, 2026 (part 1 of 4)&quot;">​</a></h3><p>This part of the title funds the Department of Transportation’s central offices and major aviation, highway, motor carrier, and traffic safety programs for fiscal year 2026. It supports transportation research, infrastructure grants, air traffic control and airport improvements, federal-aid highways, bridge and truck-parking projects, rural and Tribal infrastructure, and safety enforcement. It also reallocates some unused prior-year funds and sets detailed conditions for spending, transfers, reporting, and congressional oversight.</p><p><strong>Key takeaways:</strong></p><ul><li>The title provides $13.71 billion for Federal Aviation Administration operations, $4 billion for aviation facilities and equipment, $290 million for aviation research and development, and $4 billion for the main airport grant program.</li><li>It caps fiscal year 2026 federal-aid highway obligations at about $62.66 billion and provides about $2.40 billion more for specified highway infrastructure projects and programs.</li><li>Targeted highway funding includes $350 million for bridge projects in qualifying States, $200 million for Tribal transportation, $200 million for commercial truck parking, and $30 million for eligible Reconnecting Communities construction grants.</li><li>The title funds motor carrier safety operations and grants, highway traffic safety research, and approximately $849.7 million in State and national highway safety grants.</li><li>It provides $145 million for local and regional transportation grants, requires at least 5 percent to go to historically disadvantaged communities or areas of persistent poverty, and directs the Department to balance urban, rural, Tribal, geographic, and transportation-mode needs.</li><li>The title preserves the FAA’s public air traffic control functions, protects contract tower and weather observer programs, limits certain organizational and funding changes, and requires regular reports to Congress on aviation safety, staffing, spending, and air traffic control modernization.</li></ul><h3 id="division-d-transportation-housing-and-urban-development-and-related-agencies-appropriations-act-2026-part-2-of-4" tabindex="-1">DIVISION D, TRANSPORTATION, HOUSING AND URBAN DEVELOPMENT, AND RELATED AGENCIES APPROPRIATIONS ACT, 2026 (part 2 of 4) <a class="header-anchor" href="#division-d-transportation-housing-and-urban-development-and-related-agencies-appropriations-act-2026-part-2-of-4" aria-label="Permalink to &quot;DIVISION D, TRANSPORTATION, HOUSING AND URBAN DEVELOPMENT, AND RELATED AGENCIES APPROPRIATIONS ACT, 2026 (part 2 of 4)&quot;">​</a></h3><p>This part of the title funds federal railroad, public transit, maritime, pipeline and hazardous-materials safety, and transportation oversight programs for fiscal year 2026. It supports Amtrak, rail and transit infrastructure, ports and merchant shipping, maritime academies, pipeline safety, and transportation for major international sporting events, while setting conditions on how the money may be used.</p><p><strong>Key takeaways:</strong></p><ul><li>The title provides major rail funding, including $850 million for Amtrak’s Northeast Corridor, $1.577 billion for Amtrak’s National Network, and funding for rail safety, research, intercity passenger rail, and infrastructure grants.</li><li>It generally bars Amtrak from reducing specified long-distance service, limits individual employee overtime payments unless waived for safety or efficiency, and prevents reductions in Amtrak police staffing below the May 1, 2019 level.</li><li>The title provides $14.642 billion for transit formula programs, $1.7 billion for major transit capital projects, $150 million for the Washington metropolitan transit system, and additional funding for ferries, transit safety, technical assistance, and congressionally designated projects.</li><li>It redirects $94.3 million to transportation needs for the 2028 Olympic and Paralympic events and $100.25 million to transit agencies serving U.S. host cities for the 2026 FIFA World Cup.</li><li>Maritime funding supports the U.S.-flag merchant fleet, security fleets, the Merchant Marine Academy, State Maritime Academies, small shipyards, vessel disposal, marine highways, and port infrastructure.</li><li>The title funds pipeline and hazardous-materials safety, emergency preparedness, and the Transportation Department inspector general, while also rescinding or transferring selected unused prior-year balances and imposing congressional notice and oversight requirements.</li></ul><h3 id="division-d-transportation-housing-and-urban-development-and-related-agencies-appropriations-act-2026-part-3-of-4" tabindex="-1">DIVISION D, TRANSPORTATION, HOUSING AND URBAN DEVELOPMENT, AND RELATED AGENCIES APPROPRIATIONS ACT, 2026 (part 3 of 4) <a class="header-anchor" href="#division-d-transportation-housing-and-urban-development-and-related-agencies-appropriations-act-2026-part-3-of-4" aria-label="Permalink to &quot;DIVISION D, TRANSPORTATION, HOUSING AND URBAN DEVELOPMENT, AND RELATED AGENCIES APPROPRIATIONS ACT, 2026 (part 3 of 4)&quot;">​</a></h3><p>This title funds the Department of Housing and Urban Development’s operations and major housing and community development programs for fiscal year 2026. It supports rental assistance, public and Tribal housing, homelessness services, affordable housing development, housing for older adults and people with disabilities, fair housing enforcement, hazard reduction, mortgage guarantees, research, and oversight.</p><p><strong>Key takeaways:</strong></p><ul><li>The title provides funding for HUD leadership, administrative and program offices, information technology, inspections, research, and the Office of Inspector General.</li><li>It supplies more than $38 billion for tenant-based rental assistance, including voucher renewals, tenant protection, program administration, veterans’ housing vouchers, and family unification vouchers.</li><li>It provides about $8.3 billion for public housing operations, capital improvements, financial shortfalls, emergency repairs, health and safety hazards, and support for troubled housing agencies.</li><li>It funds Native American and Native Hawaiian housing programs, including block grants, community development grants, rental assistance, technical assistance, and loan guarantees.</li><li>It supports community development, affordable housing production, homelessness programs, housing for people with AIDS, older adults, and people with disabilities, and project-based rental assistance.</li><li>It funds fair housing enforcement and education, housing counseling, eviction legal assistance, lead and healthy-homes programs, and home modifications that help low-income older adults remain in their homes.</li></ul><h3 id="division-d-transportation-housing-and-urban-development-and-related-agencies-appropriations-act-2026-part-4-of-4" tabindex="-1">DIVISION D, TRANSPORTATION, HOUSING AND URBAN DEVELOPMENT, AND RELATED AGENCIES APPROPRIATIONS ACT, 2026 (part 4 of 4) <a class="header-anchor" href="#division-d-transportation-housing-and-urban-development-and-related-agencies-appropriations-act-2026-part-4-of-4" aria-label="Permalink to &quot;DIVISION D, TRANSPORTATION, HOUSING AND URBAN DEVELOPMENT, AND RELATED AGENCIES APPROPRIATIONS ACT, 2026 (part 4 of 4)&quot;">​</a></h3><p>This part sets operating, oversight, and funding rules for HUD programs in 2026, including rental assistance, public housing, homelessness programs, housing inspections, grant administration, and affordable housing preservation. It also funds several transportation, accessibility, housing, and homelessness-related agencies and establishes government-wide controls for money provided by this division. It rescinds specified unused funds and corrects names, recipients, purposes, accounts, and amounts for numerous previously approved projects and 2026 appropriations.</p><p><strong>Key takeaways:</strong></p><ul><li>HUD may transfer assistance, debt, and affordability requirements from failing or obsolete multifamily properties to suitable properties while protecting tenants and generally preserving assisted units and federal support.</li><li>Owners receiving housing assistance must maintain safe and sanitary properties, and HUD must act against serious inspection failures through remedies such as management replacement, penalties, subsidy reductions, ownership transfers, or tenant relocation assistance.</li><li>The title limits eligibility for rental assistance for certain students, caps salaries paid with specified public housing funds, preserves assistance during foreclosure or property disposition when feasible, and allows several forms of flexibility for vouchers and public housing agencies.</li><li>HUD must competitively award assistance unless another rule applies, notify Congress about specified grant and funding actions, follow public-comment requirements for rulemaking and contract revisions, and provide detailed financial, staffing, and enforcement reports.</li><li>The act funds the Access Board, Federal Maritime Commission, Amtrak Inspector General, National Transportation Safety Board, Neighborhood Reinvestment Corporation, Surface Transportation Board, and United States Interagency Council on Homelessness.</li><li>General provisions restrict fund transfers, lobbying, improper training, first-class travel, certain eminent-domain projects, contractor bonuses for poor performance, and other uses of appropriations, while requiring Buy American compliance, inspector general access, and public access to grant information.</li></ul><h3 id="division-e-financial-services-and-general-government-appropriations-act-2026-part-1-of-3" tabindex="-1">DIVISION E, FINANCIAL SERVICES AND GENERAL GOVERNMENT APPROPRIATIONS ACT, 2026 (part 1 of 3) <a class="header-anchor" href="#division-e-financial-services-and-general-government-appropriations-act-2026-part-1-of-3" aria-label="Permalink to &quot;DIVISION E, FINANCIAL SERVICES AND GENERAL GOVERNMENT APPROPRIATIONS ACT, 2026 (part 1 of 3)&quot;">​</a></h3><p>This part of the act provides fiscal year 2026 funding for the Department of the Treasury, the Internal Revenue Service, the Executive Office of the President, the federal judiciary, and specified District of Columbia programs. It supports tax administration and enforcement, financial-crime and cybersecurity work, community development, White House and federal drug-control operations, federal courts and public defense, and D.C. courts, public safety, education, and other services. It also sets spending limits, transfer rules, reporting duties, and restrictions on how these funds may be used.</p><p><strong>Key takeaways:</strong></p><ul><li>The act funds Treasury operations, financial intelligence, cybersecurity, inspectors general, the Financial Crimes Enforcement Network, the Fiscal Service, alcohol and tobacco regulation, and the United States Mint.</li><li>It provides $324 million for the Community Development Financial Institutions Fund, including targeted support for high-poverty areas, Native communities, healthy-food financing, small-dollar loans, and persistent-poverty counties.</li><li>It funds IRS taxpayer services, enforcement, and technology and operations, while requiring taxpayer-rights training, protection of confidential information, identity-theft safeguards, improved telephone assistance, and detailed reporting on major technology investments.</li><li>It funds the White House and other presidential offices, national cyber and drug-control programs, and requires budget-impact statements for covered executive orders and presidential memoranda issued or revoked during fiscal year 2026.</li><li>It funds the Supreme Court and other federal courts, federal defender services, jurors, court security, judicial administration, and a courthouse-security pilot administered by the United States Marshals Service.</li><li>It provides federal and local funding authority for District of Columbia programs, including courts, public defense, offender supervision, college tuition assistance, emergency security, school improvement, HIV/AIDS services, and water infrastructure.</li></ul><h3 id="division-e-financial-services-and-general-government-appropriations-act-2026-part-2-of-3" tabindex="-1">DIVISION E, FINANCIAL SERVICES AND GENERAL GOVERNMENT APPROPRIATIONS ACT, 2026 (part 2 of 3) <a class="header-anchor" href="#division-e-financial-services-and-general-government-appropriations-act-2026-part-2-of-3" aria-label="Permalink to &quot;DIVISION E, FINANCIAL SERVICES AND GENERAL GOVERNMENT APPROPRIATIONS ACT, 2026 (part 2 of 3)&quot;">​</a></h3><p>This title funds a broad range of independent agencies for fiscal year 2026, including financial and consumer regulators, election agencies, federal workforce bodies, the General Services Administration, the National Archives, the Small Business Administration, and agency inspectors general. It also finances federal buildings, election security, government technology, small-business assistance and lending, postal services, and records preservation, while setting restrictions and oversight requirements on how funds may be used.</p><p><strong>Key takeaways:</strong></p><ul><li>The title provides operating funds for major regulators including the Commodity Futures Trading Commission, Federal Communications Commission, Federal Trade Commission, Securities and Exchange Commission, Consumer Product Safety Commission, and Federal Election Commission.</li><li>It provides $45 million in election security grants to states, requires a 20 percent state match within two years, and requires quarterly financial and annual progress reports.</li><li>It bars funds from being used to ban gas stoves as a class of products, restricts action on recreational off-highway vehicle standards pending a scientific study, and blocks specified FCC, FTC, and SEC regulatory actions.</li><li>It makes nearly $9.7 billion available from the Federal Buildings Fund for construction, repairs, leased space, and building operations, subject to congressional approval and transfer controls.</li><li>It funds Small Business Administration operations, entrepreneurial development programs, business and disaster lending, and targeted assistance for women, veterans, Native Americans, exporters, microbusinesses, and other entrepreneurs.</li><li>It imposes government-wide controls on reprogramming, conferences, travel, contracting, public communications, inspector general access, abortion coverage, and agency reporting, while rescinding $300 million from the Treasury Forfeiture Fund and remaining prior-year funds for the Special Inspector General for Pandemic Recovery.</li></ul><h3 id="division-e-financial-services-and-general-government-appropriations-act-2026-part-3-of-3" tabindex="-1">DIVISION E, FINANCIAL SERVICES AND GENERAL GOVERNMENT APPROPRIATIONS ACT, 2026 (part 3 of 3) <a class="header-anchor" href="#division-e-financial-services-and-general-government-appropriations-act-2026-part-3-of-3" aria-label="Permalink to &quot;DIVISION E, FINANCIAL SERVICES AND GENERAL GOVERNMENT APPROPRIATIONS ACT, 2026 (part 3 of 3)&quot;">​</a></h3><p>This title sets government-wide rules for how federal agencies may spend fiscal year 2026 funds, covering employee conduct and pay, contracts, travel, training, privacy, public communications, conferences, interagency projects, and congressional oversight. It also sets spending and operating rules for the District of Columbia, restricts certain uses of federal and local D.C. funds, provides continuity for D.C. local spending in fiscal year 2027, and increases D.C. college tuition assistance limits.</p><p><strong>Key takeaways:</strong></p><ul><li>Federal agencies must maintain drug-free workplace policies and comply with restrictions on vehicle purchases, office renovations, employee training, publicity, lobbying, internet monitoring, and disclosure of personal or nonpublic information.</li><li>The title protects federal employees’ communications with Congress and lawful whistleblower disclosures, and it bars funding for contracts that restrict reporting of fraud, waste, or abuse.</li><li>It limits contracts and other federal assistance involving certain inverted corporations, corporations with serious unpaid federal taxes, or corporations recently convicted of federal felonies, while allowing specified government-interest or national-security exceptions.</li><li>It freezes 2026 pay rates for the Vice President, Executive Schedule officials, ambassadors, and certain highly paid political appointees, while separately setting limits and minimum adjustments for prevailing-rate federal employees.</li><li>District of Columbia funds may not be used for most abortions or to legalize or reduce penalties for recreational Schedule I drugs, and several other restrictions govern D.C. vehicles, lobbying, budget changes, and use of federal funds.</li><li>The title allows D.C. local operations to continue during specified fiscal year 2027 funding gaps and raises annual and lifetime tuition-assistance limits under the D.C. College Access Program.</li></ul><h3 id="division-f-national-security-department-of-state-and-related-programs-appropriations-act-2026-part-1-of-4" tabindex="-1">DIVISION F, NATIONAL SECURITY, DEPARTMENT OF STATE, AND RELATED PROGRAMS APPROPRIATIONS ACT, 2026 (part 1 of 4) <a class="header-anchor" href="#division-f-national-security-department-of-state-and-related-programs-appropriations-act-2026-part-1-of-4" aria-label="Permalink to &quot;DIVISION F, NATIONAL SECURITY, DEPARTMENT OF STATE, AND RELATED PROGRAMS APPROPRIATIONS ACT, 2026 (part 1 of 4)&quot;">​</a></h3><p>This part of the 2026 appropriations law funds the State Department, diplomacy and embassy security, international organizations, foreign assistance, global health, humanitarian relief, security assistance, and international broadcasting. It also supports the Peace Corps, democracy and exchange programs, development finance, multilateral development institutions, and export assistance. The law sets funding levels, deadlines, oversight requirements, and restrictions on how these funds may be used.</p><p><strong>Key takeaways:</strong></p><ul><li>The law provides $9.36 billion for State Department diplomatic programs, including personnel, overseas operations, policy support, and worldwide security protection.</li><li>It funds embassy facilities, passport and visa services, educational and cultural exchanges, international broadcasting, international organizations, and United Nations peacekeeping.</li><li>It provides major foreign assistance funding, including $9.42 billion for global health programs, $5.4 billion for humanitarian assistance, and $6.77 billion for national security investment programs.</li><li>Global health assistance covers maternal and child health, infectious diseases, emerging health threats, and voluntary family planning, while prohibiting funding for coercive abortion, involuntary sterilization, or abortion as a family-planning method.</li><li>The law funds counternarcotics, nonproliferation, demining, peacekeeping, military training, and $6.16 billion in foreign military financing, with congressional notice and oversight requirements.</li><li>It supports multilateral development institutions, the Export-Import Bank, the International Development Finance Corporation, the Peace Corps, democracy programs, and other international development agencies.</li></ul><h3 id="division-f-national-security-department-of-state-and-related-programs-appropriations-act-2026-part-2-of-4" tabindex="-1">DIVISION F, NATIONAL SECURITY, DEPARTMENT OF STATE, AND RELATED PROGRAMS APPROPRIATIONS ACT, 2026 (part 2 of 4) <a class="header-anchor" href="#division-f-national-security-department-of-state-and-related-programs-appropriations-act-2026-part-2-of-4" aria-label="Permalink to &quot;DIVISION F, NATIONAL SECURITY, DEPARTMENT OF STATE, AND RELATED PROGRAMS APPROPRIATIONS ACT, 2026 (part 2 of 4)&quot;">​</a></h3><p>This title sets government-wide rules for using and overseeing fiscal year 2026 State Department, national security, foreign assistance, and related funds. It requires extensive reporting and advance consultation with Congress, limits assistance to certain governments and activities, and directs funding toward aid evaluation, economic resilience, democracy, religious freedom, anti-corruption, diplomatic security, and law enforcement. It also establishes standards for international financial institutions, security assistance, diplomatic operations, records management, and financial transparency.</p><p><strong>Key takeaways:</strong></p><ul><li>Agencies must regularly report unused and unspent balances, publicly post most required reports, preserve federal records, strengthen cybersecurity, and notify Congress before major program or funding changes.</li><li>The title generally bars direct aid to Cuba, North Korea, and Iran and restricts aid to governments involved in military coups, terrorism, prolonged loan defaults, significant corruption, gross human rights violations, or misuse of United States assistance, while allowing specified exceptions or national-interest waivers.</li><li>Foreign assistance must generally be exempt from foreign taxation, evaluated for effectiveness, informed by beneficiary feedback, and disclosed through ForeignAssistance.gov, with at least $15 million provided for impact evaluations.</li><li>The title provides at least $155 million for an Economic Resilience Initiative, at least $185.25 million for global energy security programs, $40 million for international religious freedom programs, and $15 million for forensic assistance related to trafficking and mass atrocities.</li><li>It supports democracy, civil society, journalists, accountable policing, humane prison conditions, combat casualty care, and humanitarian-law training, while restricting support involving child soldiers, certain cluster munitions, abusive crowd-control units, abortion as a method of family planning, and involuntary sterilization.</li><li>The title requires congressional oversight of diplomatic construction, interagency transfers, foreign military financing, arms-related assistance, aid suspensions, and assistance to specifically listed countries, and it prohibits moving the United States embassy in Israel outside Jerusalem.</li></ul><h3 id="division-f-national-security-department-of-state-and-related-programs-appropriations-act-2026-part-3-of-4" tabindex="-1">DIVISION F, NATIONAL SECURITY, DEPARTMENT OF STATE, AND RELATED PROGRAMS APPROPRIATIONS ACT, 2026 (part 3 of 4) <a class="header-anchor" href="#division-f-national-security-department-of-state-and-related-programs-appropriations-act-2026-part-3-of-4" aria-label="Permalink to &quot;DIVISION F, NATIONAL SECURITY, DEPARTMENT OF STATE, AND RELATED PROGRAMS APPROPRIATIONS ACT, 2026 (part 3 of 4)&quot;">​</a></h3><p>This part directs fiscal year 2026 foreign affairs funding toward countering synthetic drugs, supporting key allies and regional security, promoting democracy and human rights, improving global health, and empowering women and girls. It sets country-specific funding levels and conditions across the Middle East, Africa, Asia, Latin America, Europe, and the Pacific, while restricting aid to terrorist groups, hostile governments, and governments that fail specified standards. It also imposes oversight, reporting, auditing, and anti-diversion requirements for assistance to the West Bank, Gaza, international organizations, and other recipients.</p><p><strong>Key takeaways:</strong></p><ul><li>At least $150 million in additional funding must support efforts to stop fentanyl, its precursor chemicals, and other synthetic drugs from reaching the United States.</li><li>Aid involving Palestinian statehood, the Palestinian Authority, the West Bank, and Gaza is subject to peace, counterterrorism, financial accountability, vetting, auditing, and anti-diversion conditions, and no aid may go to Hamas, the Palestine Liberation Organization, or the Palestinian Broadcasting Corporation.</li><li>The title provides major security and economic assistance for partners including Israel, Egypt, Jordan, Taiwan, the Philippines, Pacific Island countries, and nations implementing the Indo-Pacific Strategy, while funding programs to counter Chinese and Russian influence.</li><li>Country-specific restrictions bar or condition assistance to governments or entities including Russia, China, North Korea, the Taliban, Iran-sanctioned actors, terrorist-controlled Lebanese forces, and certain governments that undermine neighboring countries or fail stated governance, security, human-rights, or cooperation standards.</li><li>United Nations and other international organization funding is tied to financial transparency, whistleblower protection, anti-terrorist vetting, action against anti-Israel bias, access for United States auditors, and accountability for sexual exploitation or abuse by peacekeepers.</li><li>The title funds internet freedom, pandemic preparedness, infectious-disease programs, family planning and reproductive health, women’s economic and political participation, and efforts to prevent gender-based violence, while prohibiting funds for torture or the Wuhan Institute of Virology.</li></ul><h3 id="division-f-national-security-department-of-state-and-related-programs-appropriations-act-2026-part-4-of-4" tabindex="-1">DIVISION F, NATIONAL SECURITY, DEPARTMENT OF STATE, AND RELATED PROGRAMS APPROPRIATIONS ACT, 2026 (part 4 of 4) <a class="header-anchor" href="#division-f-national-security-department-of-state-and-related-programs-appropriations-act-2026-part-4-of-4" aria-label="Permalink to &quot;DIVISION F, NATIONAL SECURITY, DEPARTMENT OF STATE, AND RELATED PROGRAMS APPROPRIATIONS ACT, 2026 (part 4 of 4)&quot;">​</a></h3><p>This part sets minimum funding levels for education, conservation, food security, anti-trafficking, water and sanitation, stabilization, disaster preparedness, and other foreign assistance programs. It imposes congressional reporting, consultation, financial-management, and reorganization controls on the State Department and related agencies, while extending consular funding authorities and limiting counter-disinformation programs to foreign actors abroad. It also authorizes participation in multilateral development banks, creates a flexible national security assistance fund, and cancels about $1.94 billion in unused prior-year funding.</p><p><strong>Key takeaways:</strong></p><ul><li>At least $691.5 million is provided for basic and secondary education, $203.25 million for higher education, and $720 million for food security and agricultural development.</li><li>The measure directs substantial funding to biodiversity, anti-poaching, anti-logging, land protection, disability rights, human trafficking prevention, water and sanitation, stabilization, and disaster preparedness.</li><li>Agencies must provide Congress with detailed operating and spending plans, and major reorganizations, overseas presence changes, or workforce changes require advance congressional consultation and notification.</li><li>Up to $850 million may support the America First Opportunity Fund for crisis response, strategic partnerships, and efforts to counter adversaries.</li><li>The United States may support new contributions and capital increases for major development institutions and must advocate for multilateral financing of qualifying nuclear energy technologies.</li><li>The measure permanently cancels about $1.94 billion in unused prior-year funds across several State Department and foreign assistance accounts, while protecting previously designated emergency funding.</li></ul><h3 id="division-g-other-matters" tabindex="-1">DIVISION G, OTHER MATTERS <a class="header-anchor" href="#division-g-other-matters" aria-label="Permalink to &quot;DIVISION G, OTHER MATTERS&quot;">​</a></h3><p>This division bars State Department, foreign operations, and related appropriations from being used for contributions, grants, or other payments to the United Nations Relief and Works Agency (UNRWA). The restriction covers funds from prior fiscal years and fiscal year 2026, and applies to fiscal year 2027 funds through March 25, 2027.</p><p><strong>Key takeaways:</strong></p><ul><li>The funding ban applies despite other provisions in the Act or other laws.</li><li>No covered funds from prior fiscal years or fiscal year 2026 may be paid to UNRWA.</li><li>Fiscal year 2027 funds may not be paid to UNRWA until after March 25, 2027.</li><li>The restriction covers contributions, grants, and any other payments to UNRWA.</li></ul><h3 id="division-h-further-continuing-appropriations-act-2026" tabindex="-1">DIVISION H, FURTHER CONTINUING APPROPRIATIONS ACT, 2026 <a class="header-anchor" href="#division-h-further-continuing-appropriations-act-2026" aria-label="Permalink to &quot;DIVISION H, FURTHER CONTINUING APPROPRIATIONS ACT, 2026&quot;">​</a></h3><p>This division extends temporary federal funding through February 13, 2026, and treats the funding period as covering the lapse in appropriations that began around January 31, 2026. It provides for personnel compensation related to the lapse, approves certain obligations incurred to maintain essential government operations or shut down operations in an orderly way, and repeals an earlier provision affecting 2026 continuing appropriations.</p><p><strong>Key takeaways:</strong></p><ul><li>Temporary federal funding is extended through February 13, 2026.</li><li>The funding period includes the lapse in appropriations that began around January 31, 2026.</li><li>Available funds must be used to make required personnel pay, allowance, and benefit payments related to the funding lapse.</li><li>Certain obligations incurred to protect life and property, maintain essential activity, carry out otherwise authorized purposes, or shut down government functions in an orderly way are approved if they comply with the applicable appropriations laws.</li><li>Section 213 of title II of division C of the earlier 2026 continuing appropriations law, along with its amendments, is repealed and has no effect.</li></ul><h3 id="division-i-authorizing-extenders-and-technical-corrections" tabindex="-1">DIVISION I, AUTHORIZING EXTENDERS AND TECHNICAL CORRECTIONS <a class="header-anchor" href="#division-i-authorizing-extenders-and-technical-corrections" aria-label="Permalink to &quot;DIVISION I, AUTHORIZING EXTENDERS AND TECHNICAL CORRECTIONS&quot;">​</a></h3><p>This division extends a wide range of federal programs and authorities, including grain standards, flood insurance, transportation security, cybersecurity, immigration programs, trade preferences, and the U.S. Parole Commission. It also authorizes possible additional H-2B visas for fiscal year 2026, sets a deadline for sentencing guidelines, adjusts bankruptcy fee rules, and provides retroactive trade benefits for eligible imports from sub-Saharan Africa and Haiti. Its budget effects are excluded from specified federal pay-as-you-go scorecards and other budget calculations.</p><p><strong>Key takeaways:</strong></p><ul><li>Several agriculture, homeland security, transportation, cybersecurity, technology, immigration, and rural health authorities are extended through 2026.</li><li>The National Flood Insurance Program and its financing authority are extended through September 30, 2026, with special retroactive treatment if the law is enacted after January 30, 2026.</li><li>The U.S. Parole Commission is protected from expiration from October 1, 2025, through January 30, 2031, and the additional special assessment in federal criminal cases is continued without the former September 30, 2025, end date.</li><li>The Department of Homeland Security may authorize additional H-2B temporary nonagricultural visas for fiscal year 2026 if available U.S. workers cannot meet business needs, subject to a stated numerical ceiling.</li><li>Trade preferences under the African Growth and Opportunity Act and Haiti’s economic support program are extended through December 31, 2026, with procedures for eligible importers to seek retroactive duty treatment.</li><li>The Sentencing Commission must issue specified guidelines by December 31, 2026, while the division also revises bankruptcy fee rules and excludes its budget effects from designated budget enforcement calculations.</li></ul><h3 id="division-j-health-care-extenders-part-1-of-4" tabindex="-1">DIVISION J, HEALTH CARE EXTENDERS (part 1 of 4) <a class="header-anchor" href="#division-j-health-care-extenders-part-1-of-4" aria-label="Permalink to &quot;DIVISION J, HEALTH CARE EXTENDERS (part 1 of 4)&quot;">​</a></h3><p>This part of the Health Care Extenders division changes Medicaid rules for out-of-state providers, working adults with disabilities, military families, maternity-care cost reporting, and hospitals that serve many uninsured or Medicaid patients. It also provides implementation funding and adjusts federal Medicaid hospital funding and payment limits.</p><p><strong>Key takeaways:</strong></p><ul><li>States must create a streamlined five-year Medicaid and CHIP enrollment process for qualified, low-risk out-of-state providers serving enrolled people under age 21, effective three years after enactment.</li><li>The title removes the upper age limit from certain optional Medicaid eligibility pathways for working adults with disabilities, while giving states with existing programs until January 1, 2028, to comply.</li><li>Beginning January 1, 2030, states must protect Medicaid residency, home- and community-based services waiting-list status, and certain coverage for qualifying military members and dependents who relocate because of active-duty service.</li><li>States must periodically study the costs and payment rates for maternity, labor, and delivery services at certain rural hospitals and hospitals where Medicaid or CHIP finances most births, and HHS must publish the findings.</li><li>The title provides $10 million to help qualifying small rural hospitals compile maternity-care cost data, $3 million for broader implementation of the studies, and $1 million annually for fiscal years 2026 through 2030 to implement the military-family provisions.</li><li>The title extends specified Medicaid disproportionate share hospital funding for Tennessee, delays certain nationwide funding reductions until fiscal year 2028, and revises hospital payment limits and rules for using prior unspent allotments.</li></ul><h3 id="division-j-health-care-extenders-part-2-of-4" tabindex="-1">DIVISION J, HEALTH CARE EXTENDERS (part 2 of 4) <a class="header-anchor" href="#division-j-health-care-extenders-part-2-of-4" aria-label="Permalink to &quot;DIVISION J, HEALTH CARE EXTENDERS (part 2 of 4)&quot;">​</a></h3><p>This title extends and changes a wide range of Medicare, human services, and public health programs. It continues hospital, ambulance, telehealth, home-based care, community health, diabetes, family assistance, and health-security support, while adding Medicare coverage and beneficiary protections. It also strengthens oversight of Medicare Advantage provider directories, pharmacies, pharmacy benefit managers, medical equipment billing, and other health care practices.</p><p><strong>Key takeaways:</strong></p><ul><li>Medicare payment extensions continue support for certain rural and low-volume hospitals, ambulance services, eligible alternative payment models, clinical laboratories, hospice care, and physician services in lower-cost geographic areas.</li><li>Telehealth flexibilities generally continue through 2027, the Acute Hospital Care at Home initiative continues through September 2030, and temporary in-home cardiopulmonary rehabilitation and virtual diabetes prevention options are authorized.</li><li>The title adds Medicare coverage for qualifying multi-cancer early detection tests beginning in 2029 and for certain external infusion pumps and professionally administered home infusion drugs.</li><li>Beginning in 2028 or 2029, Medicare Advantage plans, Part D plans, pharmacies, and pharmacy benefit managers face stronger requirements concerning provider-directory accuracy, pharmacy participation, contract fairness, compensation, reporting, audits, and enforcement.</li><li>The title extends or funds human services and public health programs, including Temporary Assistance for Needy Families, youth education programs, family health information centers, community health centers, the National Health Service Corps, teaching health centers, special diabetes programs, health-security programs, and No Surprises Act implementation.</li><li>The title revises long-term funding for the World Trade Center Health Program and requires studies or guidance on hospital-at-home care, fraud risks, language access in telehealth, medication-related movement disorders, wearable medical devices, and other Medicare issues.</li></ul><h3 id="division-j-health-care-extenders-part-3-of-4" tabindex="-1">DIVISION J, HEALTH CARE EXTENDERS (part 3 of 4) <a class="header-anchor" href="#division-j-health-care-extenders-part-3-of-4" aria-label="Permalink to &quot;DIVISION J, HEALTH CARE EXTENDERS (part 3 of 4)&quot;">​</a></h3><p>This part extends and updates federal programs addressing maternal and infant health, organ donation and transplantation, pediatric drug development, sickle cell disease, caregiver respite, and health care worker mental health. It also strengthens FDA requirements and incentives involving pediatric and rare-disease drugs, narrows orphan-drug exclusivity to approved uses, and creates an FDA office in an Abraham Accords country to support regulatory cooperation.</p><p><strong>Key takeaways:</strong></p><ul><li>Maternal health provisions improve maternal death reviews and death-record reporting, require annual sharing of prevention best practices, and provide $100 million annually for fiscal years 2026 through 2030.</li><li>Organ transplantation provisions promote electronic health-record connectivity, allow temporary candidate registration fees with public reporting and congressional review, and expand reimbursement access for living donors without considering the organ recipient’s income.</li><li>The title renews or increases support for pediatric drug studies, sickle cell programs, lifespan respite care, prematurity research, and programs protecting health care workers’ mental health.</li><li>Prematurity provisions require an interagency working group and a National Academies study of preterm birth costs, risk factors, prevention strategies, treatments, and family support needs.</li><li>FDA provisions expand pediatric cancer study requirements, permit penalties for failures to complete required pediatric studies when due diligence is lacking, extend rare pediatric disease priority review vouchers through September 30, 2029, and require reports evaluating these policies.</li><li>The title limits orphan-drug exclusivity to the same approved use or indication and establishes an FDA Abraham Accords Office to provide technical assistance and improve regulatory coordination with participating countries.</li></ul><h3 id="division-j-health-care-extenders-part-4-of-4" tabindex="-1">DIVISION J, HEALTH CARE EXTENDERS (part 4 of 4) <a class="header-anchor" href="#division-j-health-care-extenders-part-4-of-4" aria-label="Permalink to &quot;DIVISION J, HEALTH CARE EXTENDERS (part 4 of 4)&quot;">​</a></h3><p>This title increases oversight and transparency for pharmacy benefit managers serving employer-sponsored group health plans. It requires detailed reporting on prescription drug prices, payments, rebates, formularies, and affiliated pharmacies, and generally requires pharmacy benefit managers to pass all drug-related rebates and similar payments through to the plan or insurer. It also directs the Food and Drug Administration to give generic drug applicants clearer information about whether their proposed products match the inactive ingredients in the brand-name drug.</p><p><strong>Key takeaways:</strong></p><ul><li>For contracts entered into, renewed, or extended starting 30 months after enactment, pharmacy benefit managers must report to group health plans at least every six months, or quarterly at a plan’s request under the same terms and cost.</li><li>Reports must provide information on drug spending, participant out-of-pocket costs, pharmacy payments, rebates and other compensation, formulary decisions, broker or consultant compensation, and the use and pricing of affiliated pharmacies.</li><li>Large employers and large plans are subject to more detailed drug- and claim-level reporting rules, while all covered plans receive summary information and may have to provide participants with aggregate and claim-specific information upon request.</li><li>The reporting system must protect health information, give participants annual notice, use a standardized format established within 18 months, and remain accessible to federal regulators.</li><li>Violations may result in penalties of $10,000 per day, and knowingly providing false information may result in penalties of up to $100,000 for each false item, although good-faith compliance efforts may support a waiver or extension.</li><li>For covered contracts beginning 30 months after enactment, pharmacy benefit managers generally must pass through 100 percent of drug-related rebates, fees, discounts, and similar payments, while the FDA must provide specified ingredient-matching information to generic drug applicants and issue related guidance.</li></ul><p>Source: <a href="https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ75.xml" target="_blank" rel="noreferrer">https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ75.xml</a></p>',108))]))}});export{h as __pageData,g as default};
